            actor_wp_id bigint(20) unsigned NOT NULL DEFAULT 0,target_wp_id bigint(20) unsigned NOT NULL DEFAULT 0,pair_a bigint(20) unsigned NOT NULL DEFAULT 0,pair_b bigint(20) unsigned NOT NULL DEFAULT 0,
            payload longtext NULL,status varchar(20) NOT NULL DEFAULT 'pending',attempts int(10) unsigned NOT NULL DEFAULT 0,next_attempt_at datetime NOT NULL,last_error text NULL,processed_at datetime NULL,created_at datetime NOT NULL,updated_at datetime NOT NULL,
            PRIMARY KEY(id),UNIQUE KEY event_uuid(event_uuid),KEY queue(status,next_attempt_at),KEY pair_key(pair_a,pair_b)
