    private function load_helpers(){static $loaded=false;if($loaded)return true;$paths=array(ABSPATH.'shared/db_helpers.php',dirname(ABSPATH).'/shared/db_helpers.php');foreach($paths as $p){if(is_file($p)){require_once $p;$loaded=true;return true;}}$this->log('db_helpers.php missing',array('paths'=>$paths));return false;}
    private function db($platform){if(!$this->load_helpers())return false;$fn=$platform===self::STREAMS?'get_wowonder_db':'get_qd_db_conn';if(!function_exists($fn))return false;$db=$fn();return $db instanceof mysqli?$db:false;}
