    private function bb_status($a,$b){return function_exists('friends_check_friendship_status')?friends_check_friendship_status($a,$b):'not_friends';}
    private function bb_blocked($a,$b){if($this->bb_block_dir($a,$b)||$this->bb_block_dir($b,$a))return true;return false;}
    private function bb_block_dir($a,$b){if(!class_exists('BP_Moderation')||!class_exists('BP_Moderation_Members'))return false;$m=new BP_Moderation($b,BP_Moderation_Members::$moderation_type,$a);return !empty($m->id)&&empty($m->user_report);}
    private function refresh_ledger($a,$b,$uuid=''){
        $p=$this->pair($a,$b);$l=$this->ledger($a,$b);$changes=array('connection_state'=>'none','requested_by'=>0,'follow_a_to_b'=>function_exists('bp_is_following')&&bp_is_following(array('leader_id'=>$b,'follower_id'=>$a))?1:0,'follow_b_to_a'=>function_exists('bp_is_following')&&bp_is_following(array('leader_id'=>$a,'follower_id'=>$b))?1:0,'block_a_to_b'=>$this->bb_block_dir($p[0],$p[1])?1:0,'block_b_to_a'=>$this->bb_block_dir($p[1],$p[0])?1:0);
