    private function project_streams($a,$b){$l=$this->ledger($a,$b);$p=$this->pair($a,$b);$ab=!empty($l['follow_a_to_b']);$ba=!empty($l['follow_b_to_a']);if($ab)$this->ext_follow_upsert(self::STREAMS,$a,$b,1);else $this->ext_follow_delete(self::STREAMS,$a,$b);if($ba)$this->ext_follow_upsert(self::STREAMS,$b,$a,1);else $this->ext_follow_delete(self::STREAMS,$b,$a);}
