    private function enforce_block_bb($a,$b,$uuid){if(function_exists('friends_check_friendship_status')&&function_exists('friends_remove_friend')&&$this->bb_status($a,$b)==='is_friend'){$this->push();try{friends_remove_friend($a,$b);}finally{$this->pop();}}if(function_exists('bp_stop_following')&&function_exists('bp_is_following'))foreach(array(array($a,$b),array($b,$a)) as $d)if(bp_is_following(array('leader_id'=>$d[1],'follower_id'=>$d[0]))){$this->push();try{bp_stop_following(array('leader_id'=>$d[1],'follower_id'=>$d[0]));}finally{$this->pop();}}$this->refresh_ledger($a,$b,$uuid);}
