    public function rest_command(WP_REST_Request $request){$raw=$request->get_body();$p=json_decode($raw,true);if(!is_array($p))return new WP_Error('bzj_json','Malformed JSON',array('status'=>400));$origin=sanitize_key(isset($p['origin'])?$p['origin']:'');$op=sanitize_key(isset($p['operation'])?$p['operation']:'');$event=sanitize_text_field(isset($p['event_id'])?$p['event_id']:'');$ea=absint(isset($p['actor_id'])?$p['actor_id']:0);$et=absint(isset($p['target_id'])?$p['target_id']:0);if(!in_array($origin,array(self::STREAMS,self::SOCIALS),true)||!in_array($op,array(self::REQUEST,self::ACCEPT,self::REJECT,self::WITHDRAW,self::REMOVE,self::FOLLOW,self::UNFOLLOW,self::BLOCK,self::UNBLOCK),true)||!$this->uuid($event)||$ea<1||$et<1||$ea===$et)return new WP_Error('bzj_request','Invalid synchronization command',array('status'=>400));$auth=$this->authenticate($request,$raw,$origin);if(is_wp_error($auth))return $auth;$a=$this->wp_from_external($origin,$ea);$b=$this->wp_from_external($origin,$et);if(!$a||!$b||$a===$b)return new WP_Error('bzj_mapping','External user mapping missing',array('status'=>409));if(isset($p['authenticated_id'])&&absint($p['authenticated_id'])!==$ea)return new WP_Error('bzj_actor','Authenticated actor mismatch',array('status'=>403));if($this->event_exists($event)){return rest_ensure_response(array('success'=>true,'status'=>$this->event_status($event)==='processed'?'already_processed':'accepted','event_id'=>$event,'relationship'=>$this->ledger($a,$b)));}if(!$this->lock($a,$b))return new WP_Error('bzj_busy','Relationship pair is busy',array('status'=>503));try{$this->create_event($event,$origin,$op,$a,$b,$p);$r=$this->apply_external($origin,$op,$a,$b,$event);if(is_wp_error($r)){$this->retry($event,$r->get_error_message());return $r;}$this->processed($event);return rest_ensure_response(array('success'=>true,'status'=>'processed','event_id'=>$event,'relationship'=>$this->ledger($a,$b)));}catch(Throwable $e){$this->retry($event,$e->getMessage());$this->log('REST command failed',array('event_id'=>$event,'origin'=>$origin,'operation'=>$op,'actor'=>$a,'target'=>$b,'error'=>$e->getMessage()));return new WP_Error('bzj_internal','Synchronization failed',array('status'=>500,'event_id'=>$event));}finally{$this->unlock($a,$b);}}
